INSERT INTO quizzes (topic_id, title, title_hi, description, description_hi, difficulty, total_questions, time_limit_mins, is_previous_year, is_premium, is_published, version) VALUES (1267, '', '', '', '', 'Medium', 35, 35, 0, 0, 1, 1);
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 1, 'Match the following newly appointed Chief Justices of High Courts (Jan 2026):\n\nList-I\n(a) Meghalaya\n(b) Jharkhand\n(c) Patna\n(d) Calcutta\n\nList-II\n(i) Justice Sujoy Paul\n(ii) Justice Mahesh Sharadchandra Sonak\n(iii) Justice Revati Mohite Dere\n(iv) Justice Sangam Kumar Sahu\n\nCodes:', 'निम्नलिखित नवनियुक्त उच्च न्यायालय के मुख्य न्यायाधीशों (जनवरी 2026) का मिलान करें:\n\nसूची-I\n(a) मेघालय\n(b) झारखंड\n(c) पटना\n(d) कलकत्ता\n\nसूची-II\n(i) जस्टिस सुजॉय पॉल\n(ii) जस्टिस महेश शरदचंद्र सोनक\n(iii) जस्टिस रेवती मोहिते डेरे\n(iv) जस्टिस संगम कुमार साहू\n\nकूट:', '(a)-(iii), (b)-(ii), (c)-(iv), (d)-(i)', '(a)-(ii), (b)-(iii), (c)-(i), (d)-(iv)', '(a)-(iv), (b)-(i), (c)-(ii), (d)-(iii)', '(a)-(i), (b)-(iv), (c)-(iii), (d)-(ii)', '(a)-(iii), (b)-(ii), (c)-(iv), (d)-(i)', '(a)-(ii), (b)-(iii), (c)-(i), (d)-(iv)', '(a)-(iv), (b)-(i), (c)-(ii), (d)-(iii)', '(a)-(i), (b)-(iv), (c)-(iii), (d)-(ii)', 1, 'Justice Revati Mohite Dere became Meghalaya''s first woman CJ. Justice Mahesh Sonak was appointed in Jharkhand. Justice Sangam Kumar Sahu in Patna. Justice Sujoy Paul in Calcutta.', 'जस्टिस रेवती मोहिते डेरे मेघालय की पहली महिला मुख्य न्यायाधीश बनीं। जस्टिस महेश सोनक को झारखंड में, जस्टिस संगम कुमार साहू को पटना में और जस्टिस सुजॉय पॉल को कलकत्ता में नियुक्त किया गया।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 2, 'Consider the following statements regarding the Pradhan Mantri Matru Vandana Yojana (PMMVY):\n\n1. It is a Central Sector Scheme operating under the Ministry of Women and Child Development.\n\n2. It provides a financial incentive of Rs 5,000 for the birth of the first child.\n\n3. It provides Rs 6,000 for the birth of the second child, irrespective of the child''s gender.\n\nChoose the correct answer:', 'प्रधानमंत्री मातृ वंदना योजना (PMMVY) के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. यह महिला एवं बाल विकास मंत्रालय के तहत संचालित एक केंद्रीय क्षेत्र की योजना (Central Sector Scheme) है।\n\n2. यह पहले बच्चे के जन्म पर 5,000 रुपये का वित्तीय प्रोत्साहन प्रदान करती है।\n\n3. यह दूसरे बच्चे के जन्म पर 6,000 रुपये प्रदान करती है, चाहे बच्चे का लिंग कुछ भी हो।\n\nसही उत्तर चुनें:', '1 and 2 only', '2 only', '2 and 3 only', '1, 2 and 3', 'केवल 1 और 2', 'केवल 2', 'केवल 2 और 3', '1, 2 और 3', 2, 'Statement 2 is correct. Statement 1 is false because it is a Centrally Sponsored Scheme, not a Central Sector Scheme. Statement 3 is false because the Rs 6,000 incentive for the second child is provided only if the child is a girl.', 'कथन 2 सही है। कथन 1 गलत है क्योंकि यह एक केंद्र प्रायोजित योजना है, न कि केंद्रीय क्षेत्र की योजना। कथन 3 गलत है क्योंकि दूसरे बच्चे के लिए 6,000 रुपये का प्रोत्साहन केवल तभी प्रदान किया जाता है जब बच्चा लड़की हो।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 3, 'Match the winners of the 77th Republic Day Parade Awards (2026):\n\nList-I\n(a) Best State Tableau (Popular Choice)\n(b) Best Ministry Tableau\n(c) Best Marching Contingent (Services - Judges'' Choice)\n(d) Best Marching Contingent (Services - Popular Choice)\n\nList-II\n(i) Gujarat\n(ii) Ministry of Culture\n(iii) Indian Navy\n(iv) Assam Regiment\n\nCodes:', '77वें गणतंत्र दिवस परेड पुरस्कार (2026) के विजेताओं का मिलान करें:\n\nसूची-I\n(a) सर्वश्रेष्ठ राज्य झांकी (लोकप्रिय पसंद)\n(b) सर्वश्रेष्ठ मंत्रालय झांकी\n(c) सर्वश्रेष्ठ मार्चिंग टुकड़ी (सेवाएं - जजों की पसंद)\n(d) सर्वश्रेष्ठ मार्चिंग टुकड़ी (सेवाएं - लोकप्रिय पसंद)\n\nसूची-II\n(i) गुजरात\n(ii) संस्कृति मंत्रालय\n(iii) भारतीय नौसेना\n(iv) असम रेजिमेंट\n\nकूट:', '(a)-(ii), (b)-(i), (c)-(iii), (d)-(iv)', '(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)', '(a)-(iii), (b)-(iv), (c)-(i), (d)-(ii)', '(a)-(iv), (b)-(iii), (c)-(ii), (d)-(i)', '(a)-(ii), (b)-(i), (c)-(iii), (d)-(iv)', '(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)', '(a)-(iii), (b)-(iv), (c)-(i), (d)-(ii)', '(a)-(iv), (b)-(iii), (c)-(ii), (d)-(i)', 2, 'Gujarat won Best State Tableau in Popular Choice. The Ministry of Culture won Best Ministry Tableau. The Indian Navy won Best Marching Contingent in Judges'' Choice, and Assam Regiment in Popular Choice.', 'गुजरात ने लोकप्रिय पसंद में सर्वश्रेष्ठ राज्य की झांकी जीती। संस्कृति मंत्रालय ने सर्वश्रेष्ठ मंत्रालय की झांकी जीती। भारतीय नौसेना ने जजों की पसंद में और असम रेजिमेंट ने लोकप्रिय पसंद में सर्वश्रेष्ठ मार्चिंग टुकड़ी का पुरस्कार जीता।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 4, 'Which of the following statements correctly describes the newly proposed Battery Pack Aadhaar Number (BPAN) in India?', 'निम्नलिखित में से कौन सा कथन भारत में नव प्रस्तावित बैटरी पैक आधार नंबर (BPAN) का सही वर्णन करता है?', 'It is a 12-character alphanumeric ID without a QR code for tracking solar panels.', 'It is a 16-character unique ID exclusively for hydrogen fuel cells.', 'It is a 21-character unique ID linked to a QR code for tracing the lifecycle of EV batteries.', 'It is a 10-character code managed by UIDAI for vehicle registration.', 'यह सौर पैनलों को ट्रैक करने के लिए बिना क्यूआर कोड वाला 12-वर्णों का अल्फ़ान्यूमेरिक आईडी है।', 'यह विशेष रूप से हाइड्रोजन ईंधन सेल के लिए 16-वर्णों की एक विशिष्ट आईडी है।', 'यह ईवी (EV) बैटरी के जीवनचक्र का पता लगाने के लिए क्यूआर कोड से जुड़ी 21-वर्णों की एक विशिष्ट आईडी है।', 'यह वाहन पंजीकरण के लिए UIDAI द्वारा प्रबंधित 10-वर्णों का कोड है।', 3, 'BPAN is an indigenous digital identification system consisting of a 21-character unique ID with an accompanying QR code to trace the end-to-end lifecycle and health of EV batteries.', 'BPAN एक स्वदेशी डिजिटल पहचान प्रणाली है जिसमें 21-वर्णों की विशिष्ट आईडी और साथ में एक क्यूआर कोड होता है, जो ईवी बैटरी के संपूर्ण जीवनचक्र और स्वास्थ्य का पता लगाने के लिए है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 5, 'Who among the following has become the first Indian to be nominated to chair the UN Advisory Board on Disarmament Matters (ABDM) for the 2026-27 term?', 'निम्नलिखित में से कौन 2026-27 के कार्यकाल के लिए निरस्त्रीकरण मामलों पर संयुक्त राष्ट्र सलाहकार बोर्ड (ABDM) की अध्यक्षता करने वाले पहले भारतीय बन गए हैं?', 'Syed Akbaruddin', 'D.B. Venkatesh Varma', 'Ruchira Kamboj', 'T.S. Tirumurti', 'सैयद अकबरुद्दीन', 'डी.बी. वेंकटेश वर्मा', 'रुचिरा कंबोज', 'टी.एस. तिरुमूर्ति', 2, 'Senior Indian diplomat D.B. Venkatesh Varma has been nominated to chair the UN Disarmament Advisory Board (ABDM) for the 2026-27 term, becoming the first Indian to hold this position.', 'वरिष्ठ भारतीय राजनयिक डी.बी. वेंकटेश वर्मा को 2026-27 के कार्यकाल के लिए संयुक्त राष्ट्र निरस्त्रीकरण सलाहकार बोर्ड (ABDM) की अध्यक्षता करने के लिए नामित किया गया है, यह पद संभालने वाले वे पहले भारतीय बन गए हैं।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 6, 'Consider the following statements regarding the 86th All India Presiding Officers'' Conference:\n\n1. It was held in Lucknow, Uttar Pradesh.\n\n2. The official theme of the conference was "Strong Legislature, Prosperous Nation".\n\nChoose the correct answer:', '86वें अखिल भारतीय पीठासीन अधिकारी सम्मेलन के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. यह लखनऊ, उत्तर प्रदेश में आयोजित किया गया था।\n\n2. सम्मेलन का आधिकारिक विषय "मजबूत विधायिका, समृद्ध राष्ट्र" था।\n\nसही उत्तर चुनें:', '1 only', '2 only', 'Both 1 and 2', 'Neither 1 nor 2', 'केवल 1', 'केवल 2', '1 और 2 दोनों', 'न तो 1 और न ही 2', 3, 'Both statements are correct. The 86th All India Presiding Officers'' Conference was inaugurated in Lucknow by UP Governor Anandiben Patel. The theme was ''Strong Legislature, Prosperous Nation''.', 'दोनों कथन सही हैं। 86वें अखिल भारतीय पीठासीन अधिकारी सम्मेलन का उद्घाटन यूपी की राज्यपाल आनंदीबेन पटेल ने लखनऊ में किया। इसका विषय ''मजबूत विधायिका, समृद्ध राष्ट्र'' था।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 7, 'Match the following recently launched books with their authors/editors (Jan 2026):\n\nList-I\n(a) Premanu Vishwa Vishwanu Prem\n(b) Sing, Dance and Lead\n(c) History That India Ignored\n\nList-II\n(i) Srimad Vijay Ratna Sundar Surishwar Ji Maharaj\n(ii) Hindol Sengupta\n(iii) Prem Prakash\n\nCodes:', 'हाल ही में लॉन्च की गई निम्नलिखित पुस्तकों का उनके लेखकों/संपादकों (जनवरी 2026) के साथ मिलान करें:\n\nसूची-I\n(a) प्रेमनु विश्व विश्वानु प्रेम\n(b) सिंग, डांस एंड लीड (Sing, Dance and Lead)\n(c) हिस्ट्री दैट इंडिया इग्नोरर्ड (History That India Ignored)\n\nसूची-II\n(i) श्रीमद् विजय रत्न सुंदर सूरीश्वर जी महाराज\n(ii) हिंडोल सेनगुप्ता\n(iii) प्रेम प्रकाश\n\nकूट:', '(a)-(ii), (b)-(i), (c)-(iii)', '(a)-(i), (b)-(ii), (c)-(iii)', '(a)-(iii), (b)-(ii), (c)-(i)', '(a)-(i), (b)-(iii), (c)-(ii)', '(a)-(ii), (b)-(i), (c)-(iii)', '(a)-(i), (b)-(ii), (c)-(iii)', '(a)-(iii), (b)-(ii), (c)-(i)', '(a)-(i), (b)-(iii), (c)-(ii)', 2, '''Premanu Vishwa Vishwanu Prem'' was authored by Srimad Vijay Ratna Sundar Surishwar Ji Maharaj. ''Sing, Dance and Lead'' was authored by Hindol Sengupta. ''History That India Ignored'' was authored by Prem Prakash.', '''प्रेमनु विश्व विश्वानु प्रेम'' श्रीमद् विजय रत्न सुंदर सूरीश्वर जी महाराज द्वारा लिखी गई थी। ''सिंग, डांस एंड लीड'' हिंडोल सेनगुप्ता द्वारा लिखी गई थी। ''हिस्ट्री दैट इंडिया इग्नोरर्ड'' प्रेम प्रकाश द्वारा लिखी गई थी।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 8, 'Consider the following statements regarding the Jeevan Raksha Padak awards conferred in 2026:\n\n1. The Sarvottam Jeevan Raksha Padak carries a prize money of ₹2 Lakh.\n\n2. The Uttam Jeevan Raksha Padak carries a prize money of ₹1.5 Lakh.\n\n3. A total of 130 awards were given in 2026 across all categories.\n\nWhich of the statements given above are correct?', '2026 में प्रदान किए गए जीवन रक्षा पदक पुरस्कारों के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. सर्वोत्तम जीवन रक्षा पदक में ₹2 लाख की पुरस्कार राशि होती है।\n\n2. उत्तम जीवन रक्षा पदक में ₹1.5 लाख की पुरस्कार राशि होती है।\n\n3. 2026 में सभी श्रेणियों में कुल 130 पुरस्कार दिए गए।\n\nउपरोक्त कथनों में से कौन से सही हैं?', '1 and 2 only', '2 and 3 only', '1 and 3 only', '1, 2 and 3', 'केवल 1 और 2', 'केवल 2 और 3', 'केवल 1 और 3', '1, 2 और 3', 1, 'Statements 1 and 2 are correct. Statement 3 is false because a total of 30 awards were given in 2026, not 130 (6 Sarvottam, 6 Uttam, and 18 Jeevan Raksha).', 'कथन 1 और 2 सही हैं। कथन 3 गलत है क्योंकि 2026 में कुल 130 नहीं, बल्कि 30 पुरस्कार दिए गए (6 सर्वोत्तम, 6 उत्तम और 18 जीवन रक्षा)।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 9, 'Which of the following best describes MAPSS, recently inducted by the Indian Army?', 'निम्नलिखित में से कौन भारतीय सेना द्वारा हाल ही में शामिल किए गए MAPSS का सबसे अच्छा वर्णन करता है?', 'A nuclear-powered autonomous submarine', 'A fully electric, solar-powered Unmanned Aerial Vehicle (UAV)', 'An anti-tank guided missile with top-attack capability', 'A satellite communication terminal for remote border areas', 'एक परमाणु-संचालित स्वायत्त पनडुब्बी', 'एक पूर्णतः इलेक्ट्रिक, सौर-संचालित मानवरहित हवाई वाहन (UAV)', 'शीर्ष-हमले (top-attack) क्षमता वाली एक एंटी-टैंक गाइडेड मिसाइल', 'दूरस्थ सीमावर्ती क्षेत्रों के लिए एक उपग्रह संचार टर्मिनल', 2, 'MAPSS (Medium Altitude Persistent Surveillance System) is a fully electric, solar-powered UAV inducted by the Indian Army for surveillance, developed by NewSpace Research.', 'एमएपीएसएस (मीडियम एल्टीट्यूड पर्सिस्टेंट सर्विलांस सिस्टम) एक पूर्णतः इलेक्ट्रिक, सौर ऊर्जा संचालित यूएवी है जिसे निगरानी के लिए भारतीय सेना में शामिल किया गया है, इसे न्यूस्पेस रिसर्च द्वारा विकसित किया गया है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 10, 'Match the following international leaders appointed/elected in January 2026 with their respective countries:\n\nList-I\n(a) Mamady Doumbouya\n(b) Yoweri Museveni\n(c) Shaya Mohsin Zindani\n\nList-II\n(i) Uganda\n(ii) Yemen\n(iii) Guinea\n\nCodes:', 'जनवरी 2026 में नियुक्त/निर्वाचित निम्नलिखित अंतर्राष्ट्रीय नेताओं का उनके संबंधित देशों के साथ मिलान करें:\n\nसूची-I\n(a) ममाडी डोमबोया\n(b) योवेरी मुसेवेनी\n(c) शाया मोहसिन जिंदानी\n\nसूची-II\n(i) युगांडा\n(ii) यमन\n(iii) गिनी\n\nकूट:', '(a)-(ii), (b)-(i), (c)-(iii)', '(a)-(iii), (b)-(i), (c)-(ii)', '(a)-(i), (b)-(iii), (c)-(ii)', '(a)-(iii), (b)-(ii), (c)-(i)', '(a)-(ii), (b)-(i), (c)-(iii)', '(a)-(iii), (b)-(i), (c)-(ii)', '(a)-(i), (b)-(iii), (c)-(ii)', '(a)-(iii), (b)-(ii), (c)-(i)', 2, 'Mamady Doumbouya became the President of Guinea. Yoweri Museveni was elected President of Uganda. Shaya Mohsin Zindani became the Prime Minister of Yemen.', 'ममाडी डोमबोया गिनी के राष्ट्रपति बने। योवेरी मुसेवेनी युगांडा के राष्ट्रपति चुने गए। शाया मोहसिन जिंदानी यमन के प्रधान मंत्री बने।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 11, 'Consider the following statements regarding the Kaziranga Elevated Corridor Project:\n\n1. The Prime Minister laid the foundation stone for this 86-km long project.\n\n2. It connects Kaliabor to Nagaon district in Assam to provide safe passage for wildlife.\n\nChoose the correct answer:', 'काजीरंगा एलिवेटेड कॉरिडोर प्रोजेक्ट के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. प्रधानमंत्री ने इस 86 किलोमीटर लंबी परियोजना की आधारशिला रखी।\n\n2. यह वन्यजीवों को सुरक्षित मार्ग प्रदान करने के लिए असम में कलियाबोर को नगांव जिले से जोड़ता है।\n\nसही उत्तर चुनें:', '1 only', '2 only', 'Both 1 and 2', 'Neither 1 nor 2', 'केवल 1', 'केवल 2', '1 और 2 दोनों', 'न तो 1 और न ही 2', 3, 'Both statements are correct. PM Modi laid the foundation stone for the 86-km Kaziranga Elevated Corridor from Kaliabor to Nagaon in Assam (worth over ₹7,000 crore) to reduce human-animal conflict.', 'दोनों कथन सही हैं। पीएम मोदी ने मानव-पशु संघर्ष को कम करने के लिए असम में कलियाबोर से नगांव तक 86 किलोमीटर लंबे काजीरंगा एलिवेटेड कॉरिडोर (₹7,000 करोड़ से अधिक की लागत) की आधारशिला रखी।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 12, 'The ''Arunodaya'' special screening campaign, recently launched in January 2026, aims at the prevention and control of:', 'जनवरी 2026 में हाल ही में शुरू किए गए ''अरुणोदय'' विशेष जांच अभियान का उद्देश्य किसकी रोकथाम और नियंत्रण करना है?', 'Tuberculosis in tribal districts of Odisha', 'Sickle Cell Anemia in high-prevalence districts of Maharashtra', 'Cervical Cancer in rural areas of Gujarat', 'Malaria in the north-eastern districts of Assam', 'ओडिशा के आदिवासी जिलों में तपेदिक (Tuberculosis)', 'महाराष्ट्र के उच्च प्रसार वाले जिलों में सिकल सेल एनीमिया (Sickle Cell Anemia)', 'गुजरात के ग्रामीण क्षेत्रों में गर्भाशय ग्रीवा का कैंसर (Cervical Cancer)', 'असम के उत्तर-पूर्वी जिलों में मलेरिया', 2, 'The ''Arunodaya'' scheme was launched by the Maharashtra Government as a special screening drive across 21 high-prevalence districts aiming for a Sickle Cell Free mission state.', '''अरुणोदय'' योजना महाराष्ट्र सरकार द्वारा 21 उच्च-प्रसार वाले जिलों में एक विशेष जांच अभियान के रूप में शुरू की गई थी, जिसका लक्ष्य सिकल सेल मुक्त मिशन राज्य बनाना है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 13, 'Where was India''s first-ever Sunrise Festival, titled ''Alok Prabhat: Dance of the Dawn'', organized?', 'भारत का पहला सूर्योदय उत्सव, जिसका शीर्षक ''आलोक प्रभात: डांस ऑफ द डॉन'' था, कहाँ आयोजित किया गया था?', 'Tawang, Arunachal Pradesh', 'Dong village, Anjaw district, Arunachal Pradesh', 'Majuli, Assam', 'Kibithu, Arunachal Pradesh', 'तवांग, अरुणाचल प्रदेश', 'डोंग गांव, अंजाव जिला, अरुणाचल प्रदेश', 'माजुली, असम', 'किबिथु, अरुणाचल प्रदेश', 2, '''Alok Prabhat: Dance of the Dawn'', India''s first sunrise festival, was organized in Dong village within the Anjaw district of Arunachal Pradesh, where the first sunrise in India is witnessed.', 'भारत का पहला सूर्योदय उत्सव ''आलोक प्रभात: डांस ऑफ द डॉन'' अरुणाचल प्रदेश के अंजाव जिले के डोंग गांव में आयोजित किया गया था, जहां भारत में पहला सूर्योदय देखा जाता है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 14, 'The ''Sahasralingam'', the world''s largest black granite shivling, was recently installed at the under-construction Viraat Ramayan Mandir. This temple is located in:', 'दुनिया का सबसे बड़ा काले ग्रेनाइट का शिवलिंग ''सहस्रलिंगम'' हाल ही में निर्माणाधीन विराट रामायण मंदिर में स्थापित किया गया। यह मंदिर कहाँ स्थित है?', 'Ujjain, Madhya Pradesh', 'Ayodhya, Uttar Pradesh', 'Motihari, Bihar', 'Kanchipuram, Tamil Nadu', 'उज्जैन, मध्य प्रदेश', 'अयोध्या, उत्तर प्रदेश', 'मोतिहारी, बिहार', 'कांचीपुरम, तमिलनाडु', 3, 'The world''s largest black granite shivling, Sahasralingam, was installed at the Viraat Ramayan Mandir in Motihari, Bihar. The temple is expected to be completed by 2030.', 'दुनिया का सबसे बड़ा काले ग्रेनाइट का शिवलिंग, सहस्रलिंगम, मोतिहारी, बिहार में विराट रामायण मंदिर में स्थापित किया गया। इस मंदिर के 2030 तक पूरा होने की उम्मीद है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 15, 'Consider the following statements regarding the ''Suryastra'' Long Range Rocket System:\n\n1. It is an indigenous multi-caliber rocket launcher system capable of 150 km to 300 km surface-to-surface strikes.\n\n2. It has been developed by NIBE Ltd in collaboration with Israel''s Elbit Systems.\n\nChoose the correct answer:', '''सूर्यास्त्र'' लंबी दूरी के रॉकेट सिस्टम के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. यह एक स्वदेशी मल्टी-कैलिबर रॉकेट लॉन्चर सिस्टम है जो 150 किमी से 300 किमी तक सतह-से-सतह पर हमला करने में सक्षम है।\n\n2. इसे एनआईबीई लिमिटेड (NIBE Ltd) ने इज़राइल के एल्बिट सिस्टम्स (Elbit Systems) के सहयोग से विकसित किया है।\n\nसही उत्तर चुनें:', '1 only', '2 only', 'Both 1 and 2', 'Neither 1 nor 2', 'केवल 1', 'केवल 2', '1 और 2 दोनों', 'न तो 1 और न ही 2', 3, 'Both statements are correct. The Suryastra rocket system is a surface-to-surface long-range system (150-300 km) developed through a contract with NIBE Ltd in collaboration with Israel''s Elbit Systems.', 'दोनों कथन सही हैं। सूर्यास्त्र रॉकेट सिस्टम एक सतह-से-सतह लंबी दूरी का सिस्टम (150-300 किमी) है जिसे इज़राइल के एल्बिट सिस्टम्स के सहयोग से एनआईबीई लिमिटेड (NIBE Ltd) के साथ अनुबंध के माध्यम से विकसित किया गया है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 16, 'Consider the following statements regarding the ''Rahveer'' Scheme notified by the Union Government:\n\n1. It provides a reward of ₹25,000 and a certificate of appreciation to Good Samaritans.\n\n2. The reward is given for rescuing and hospitalizing road accident victims within the ''Golden Hour''.\n\n3. It guarantees that the Good Samaritan will not face legal or police harassment.\n\nWhich of the statements given above are correct?', 'केंद्र सरकार द्वारा अधिसूचित ''राहवीर'' योजना के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. यह ''नेक समेरिटन'' (Good Samaritans) को ₹25,000 का इनाम और एक प्रशंसा प्रमाण पत्र प्रदान करती है।\n\n2. यह इनाम ''गोल्डन आवर'' (स्वर्णिम घंटे) के भीतर सड़क दुर्घटना पीड़ितों को बचाने और अस्पताल में भर्ती कराने के लिए दिया जाता है।\n\n3. यह गारंटी देता है कि नेक समेरिटन को कानूनी या पुलिस उत्पीड़न का सामना नहीं करना पड़ेगा।\n\nउपरोक्त कथनों में से कौन से सही हैं?', '1 and 2 only', '2 and 3 only', '1 and 3 only', '1, 2 and 3', 'केवल 1 और 2', 'केवल 2 और 3', 'केवल 1 और 3', '1, 2 और 3', 4, 'All three statements are correct. The Rahveer Scheme (notified under Section 134A of Motor Vehicles Amendment Act) awards ₹25,000 to citizens helping victims within the first hour (Golden Hour) and ensures no legal harassment.', 'तीनों कथन सही हैं। राहवीर योजना (मोटर वाहन संशोधन अधिनियम की धारा 134A के तहत अधिसूचित) पहले घंटे (गोल्डन आवर) के भीतर पीड़ितों की मदद करने वाले नागरिकों को ₹25,000 का पुरस्कार देती है और यह सुनिश्चित करती है कि कोई कानूनी उत्पीड़न न हो।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 17, 'With reference to the UGC Promotion of Equity in Higher Education Institutions Regulations 2026, consider the following statements:\n\n1. It applies exclusively to Central Universities.\n\n2. It mandates the establishment of Equal Opportunity Centers (EOCs) in all applicable institutions.\n\nChoose the correct answer:', 'यूजीसी उच्च शिक्षा संस्थानों में समानता को बढ़ावा देने के विनियम 2026 के संदर्भ में, निम्नलिखित कथनों पर विचार करें:\n\n1. यह विशेष रूप से केवल केंद्रीय विश्वविद्यालयों पर लागू होता है।\n\n2. यह सभी लागू संस्थानों में समान अवसर केंद्र (EOCs) की स्थापना को अनिवार्य करता है।\n\nसही उत्तर चुनें:', '1 only', '2 only', 'Both 1 and 2', 'Neither 1 nor 2', 'केवल 1', 'केवल 2', '1 और 2 दोनों', 'न तो 1 और न ही 2', 2, 'Statement 2 is correct. Statement 1 is incorrect because the regulations apply to all Higher Education Institutions (Public, Private, and Deemed), not just Central Universities.', 'कथन 2 सही है। कथन 1 गलत है क्योंकि यह नियम केवल केंद्रीय विश्वविद्यालयों पर ही नहीं, बल्कि सभी उच्च शिक्षा संस्थानों (सार्वजनिक, निजी और डीम्ड) पर लागू होते हैं।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 18, 'Which of the following sites constitute the ''Buddhist Diamond Triangle of Odisha'', which was recently added to India''s tentative list for UNESCO World Heritage Sites?', 'निम्नलिखित में से कौन से स्थल ''ओडिशा के बौद्ध डायमंड त्रिकोण'' का निर्माण करते हैं, जिसे हाल ही में यूनेस्को की विश्व धरोहर स्थलों के लिए भारत की अस्थायी सूची में जोड़ा गया था?', 'Lalitgiri, Udayagiri, and Khandagiri', 'Lalitgiri, Udayagiri, and Ratnagiri', 'Ratnagiri, Dhauligiri, and Khandagiri', 'Udayagiri, Dhauligiri, and Lalitgiri', 'ललितगिरि, उदयगिरि और खंडगिरि', 'ललितगिरि, उदयगिरि और रत्नागिरि', 'रत्नागिरि, धौलीगिरि और खंडगिरि', 'उदयगिरि, धौलीगिरि और ललितगिरि', 2, 'The Buddhist Diamond Triangle of Odisha comprises Lalitgiri, Udayagiri, and Ratnagiri located in Jajpur and Cuttack districts. It was recently added to India''s tentative list for UNESCO.', 'ओडिशा का बौद्ध डायमंड त्रिकोण ललितगिरि, उदयगिरि और रत्नागिरि से मिलकर बना है जो जाजपुर और कटक जिलों में स्थित हैं। इसे हाल ही में यूनेस्को के लिए भारत की अस्थायी सूची में जोड़ा गया था।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 19, 'Which team won the final of the Vijay Hazare Trophy 2025-26?', 'विजय हजारे ट्रॉफी 2025-26 का फाइनल किस टीम ने जीता?', 'Saurashtra', 'Mumbai', 'Vidarbha', 'Karnataka', 'सौराष्ट्र', 'मुंबई', 'विदर्भ', 'कर्नाटक', 3, 'Vidarbha won the Vijay Hazare Trophy 2025-26 (their first title) by defeating Saurashtra by 38 runs in the final played at the BCCI Centre of Excellence in Bengaluru.', 'विदर्भ ने बेंगलुरु में BCCI सेंटर ऑफ एक्सीलेंस में खेले गए फाइनल में सौराष्ट्र को 38 रनों से हराकर विजय हजारे ट्रॉफी 2025-26 (अपना पहला खिताब) जीता।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 20, 'India''s first tropical RAS-based commercial-scale Rainbow Trout Farm and Research Institute was inaugurated in which city?', 'भारत के पहले उष्णकटिबंधीय आरएएस-आधारित (RAS-based) वाणिज्यिक पैमाने के रेनबो ट्राउट फार्म और अनुसंधान संस्थान का उद्घाटन किस शहर में किया गया?', 'Dehradun, Uttarakhand', 'Hyderabad, Telangana', 'Shimla, Himachal Pradesh', 'Gangtok, Sikkim', 'देहरादून, उत्तराखंड', 'हैदराबाद, तेलंगाना', 'शिमला, हिमाचल प्रदेश', 'गंगटोक, सिक्किम', 2, 'India''s first tropical RAS-based Rainbow Trout Farm and Research Institute was opened by Smart Green Aquaculture in Hyderabad, Telangana, aiming to farm cold-water trout year-round.', 'भारत का पहला उष्णकटिबंधीय RAS-आधारित रेनबो ट्राउट फार्म और अनुसंधान संस्थान स्मार्ट ग्रीन एक्वाकल्चर द्वारा हैदराबाद, तेलंगाना में खोला गया, जिसका उद्देश्य साल भर ठंडे पानी की ट्राउट की खेती करना है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 21, 'The ''Bhairav'' unit, recently created by the Indian Army, is best described as:', 'भारतीय सेना द्वारा हाल ही में बनाई गई ''भैरव'' इकाई को सबसे अच्छी तरह से वर्णित किया जा सकता है:', 'A specialized amphibious warfare unit deployed near the Andaman Islands.', 'A modern warfare force comprising over 1 lakh drone operatives for rapid response.', 'An all-female commando unit for UN peacekeeping missions.', 'A dedicated cyber-security and anti-hacking squad.', 'अंडमान द्वीप समूह के पास तैनात एक विशेष उभयचर युद्ध इकाई।', 'त्वरित प्रतिक्रिया के लिए 1 लाख से अधिक ड्रोन ऑपरेटरों वाली एक आधुनिक युद्ध शक्ति।', 'संयुक्त राष्ट्र शांति अभियानों के लिए एक पूर्ण-महिला कमांडो इकाई।', 'एक समर्पित साइबर-सुरक्षा और एंटी-हैकिंग दस्ता।', 2, 'The Bhairav battalion is a modern warfare force comprising over 1 lakh trained drone operatives. It acts as a bridge between regular infantry and special forces for immediate rapid response.', 'भैरव बटालियन एक आधुनिक युद्ध शक्ति है जिसमें 1 लाख से अधिक प्रशिक्षित ड्रोन ऑपरेटर शामिल हैं। यह तत्काल त्वरित प्रतिक्रिया के लिए नियमित पैदल सेना और विशेष बलों के बीच एक पुल के रूप में कार्य करता है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 22, 'Which country was the focal theme country at the 49th International Kolkata Book Fair?', '49वें अंतर्राष्ट्रीय कोलकाता पुस्तक मेले में फोकल थीम देश कौन सा था?', 'Spain', 'Qatar', 'France', 'Argentina', 'स्पेन', 'कतर', 'फ्रांस', 'अर्जेंटीना', 4, 'Argentina was the focal theme country for the 49th International Kolkata Book Fair. Qatar and Spain were guest/focus countries for the New Delhi World Book Fair, not Kolkata.', 'अर्जेंटीना 49वें अंतर्राष्ट्रीय कोलकाता पुस्तक मेले के लिए फोकल थीम देश था। कतर और स्पेन नई दिल्ली विश्व पुस्तक मेले के लिए अतिथि/फोकस देश थे, कोलकाता के लिए नहीं।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 23, 'Consider the following statements regarding the ICGS ''Samudra Pratap'':\n\n1. It is India''s first indigenously designed Pollution Control Vessel.\n\n2. It has been built by Goa Shipyard Limited.\n\nChoose the correct answer:', 'ICGS ''समुद्र प्रताप'' के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. यह भारत का पहला स्वदेशी रूप से डिजाइन किया गया प्रदूषण नियंत्रण पोत (Pollution Control Vessel) है。\n\n2. इसका निर्माण गोवा शिपयार्ड लिमिटेड (Goa Shipyard Limited) द्वारा किया गया है।\n\nसही उत्तर चुनें:', '1 only', '2 only', 'Both 1 and 2', 'Neither 1 nor 2', 'केवल 1', 'केवल 2', '1 और 2 दोनों', 'न तो 1 और न ही 2', 3, 'Both statements are correct. ICGS Samudra Pratap, commissioned by Defence Minister Rajnath Singh, is an indigenous Pollution Control Vessel built by Goa Shipyard Limited to mitigate marine oil spills.', 'दोनों कथन सही हैं। रक्षा मंत्री राजनाथ सिंह द्वारा कमीशन किया गया आईसीजीएस समुद्र प्रताप, समुद्री तेल रिसाव को कम करने के लिए गोवा शिपयार्ड लिमिटेड द्वारा निर्मित एक स्वदेशी प्रदूषण नियंत्रण पोत है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 24, 'Kirtida Mekani, who passed away in January 2026, was popularly known as the:', 'जनवरी 2026 में निधन होने वाली कीर्तिदा मेकानी को लोकप्रिय रूप से किस नाम से जाना जाता था?', 'Water Mother of India', 'Tree Lady of Singapore', 'Bird Woman of Karnataka', 'Forest Guardian of Asia', 'भारत की जल माता (Water Mother of India)', 'सिंगापुर की ट्री लेडी (Tree Lady of Singapore)', 'कर्नाटक की बर्ड वुमन (Bird Woman of Karnataka)', 'एशिया की वन रक्षक (Forest Guardian of Asia)', 2, 'Kirtida Mekani, a Karnataka-born environmentalist, was popularly known as the ''Tree Lady'' of Singapore for her lifelong dedication to nature conservation.', 'कर्नाटक में जन्मी पर्यावरणविद् कीर्तिदा मेकानी को प्रकृति संरक्षण के प्रति उनके आजीवन समर्पण के लिए सिंगापुर की ''ट्री लेडी'' के रूप में जाना जाता था।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 25, 'Which village panchayat became the first in North-West India to be certified as a fully organic gram panchayat?', 'उत्तर-पश्चिम भारत में पूर्णतः जैविक ग्राम पंचायत के रूप में प्रमाणित होने वाली पहली ग्राम पंचायत कौन सी बनी?', 'Mawlynnong, Meghalaya', 'Bamanwas Kankar, Rajasthan', 'Hiware Bazar, Maharashtra', 'Punsari, Maharashtra', 'मावलिननॉन्ग, मेघालय', 'बामनवास कांकड़, राजस्थान', 'हिवरे बाजार, महाराष्ट्र', 'पुंसारी, महाराष्ट्र', 2, 'Bamanwas Kankar village in the Kotputli-Behror district of Rajasthan became the first fully organic certified gram panchayat in North-West India.', 'राजस्थान के कोटपूतली-बहरोड़ जिले का बामनवास कांकड़ गांव उत्तर-पश्चिम भारत की पहली पूर्णतः जैविक प्रमाणित ग्राम पंचायत बन गया।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 26, 'The 16th ADMM Plus Expert Working Group on Counter-Terrorism was recently co-chaired in New Delhi by India and which other country?', 'आतंकवाद-निरोध पर 16वें ADMM प्लस विशेषज्ञ कार्य समूह (EWG) की हाल ही में नई दिल्ली में भारत और किस अन्य देश द्वारा सह-अध्यक्षता की गई?', 'Singapore', 'Indonesia', 'Malaysia', 'Vietnam', 'सिंगापुर', 'इंडोनेशिया', 'मलेशिया', 'वियतनाम', 3, 'The 16th ADMM Plus Expert Working Group on Counter-Terrorism was co-chaired by India and Malaysia in New Delhi, marking India''s continued engagement in ASEAN defense forums.', 'आतंकवाद-निरोध पर 16वें ADMM प्लस विशेषज्ञ कार्य समूह की सह-अध्यक्षता नई दिल्ली में भारत और मलेशिया द्वारा की गई, जो आसियान रक्षा मंचों में भारत की निरंतर भागीदारी को दर्शाता है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 27, 'Which of the following individuals is NOT among the recipients of the Uttar Pradesh Gaurav Samman Award 2026?', 'निम्नलिखित में से कौन उत्तर प्रदेश गौरव सम्मान पुरस्कार 2026 के प्राप्तकर्ताओं में शामिल नहीं है?', 'Shubhanshu Shukla', 'Hariom Pawar', 'Alakh Pandey', 'Manoj Bajpayee', 'शुभांशु शुक्ला', 'हरिओम पवार', 'अलख पांडे', 'मनोज बाजपेयी', 4, 'The UP Gaurav Samman 2026 was awarded to five individuals: Shubhanshu Shukla (Space Science), Alakh Pandey (Education), Sudhanshu Singh (Agriculture), Rashmi Arya (Women Empowerment), and Hariom Pawar (Literature). Manoj Bajpayee was not a recipient.', 'यूपी गौरव सम्मान 2026 पांच व्यक्तियों को प्रदान किया गया: शुभांशु शुक्ला (अंतरिक्ष विज्ञान), अलख पांडे (शिक्षा), सुधांशु सिंह (कृषि), रश्मि आर्य (महिला सशक्तिकरण), और हरिओम पवार (साहित्य)। मनोज बाजपेयी प्राप्तकर्ता नहीं थे।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 28, 'Consider the following statements regarding ''Granth Kutir'':\n\n1. It was inaugurated at the Rashtrapati Bhavan by the President of India.\n\n2. It houses a collection of manuscripts and books in 11 classical languages of India.\n\nChoose the correct answer:', '''ग्रंथ कुटीर'' के संबंध में निम्नलिखित कथनों पर विचार करें:\n\n1. इसका उद्घाटन भारत की राष्ट्रपति द्वारा राष्ट्रपति भवन में किया गया था।\n\n2. इसमें भारत की 11 शास्त्रीय भाषाओं में पांडुलिपियों और पुस्तकों का संग्रह है।\n\nसही उत्तर चुनें:', '1 only', '2 only', 'Both 1 and 2', 'Neither 1 nor 2', 'केवल 1', 'केवल 2', '1 और 2 दोनों', 'न तो 1 और न ही 2', 3, 'Both statements are correct. The President of India inaugurated Granth Kutir at the Rashtrapati Bhavan, which serves as a repository for manuscripts and texts in India''s 11 classical languages.', 'दोनों कथन सही हैं। भारत की राष्ट्रपति ने राष्ट्रपति भवन में ग्रंथ कुटीर का उद्घाटन किया, जो भारत की 11 शास्त्रीय भाषाओं में पांडुलिपियों और ग्रंथों के भंडार के रूप में कार्य करता है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 29, 'The prestigious national-level ''Saras Mela 2026'' was hosted in which city to promote women-led enterprises and rural livelihoods?', 'महिला नेतृत्व वाले उद्यमों और ग्रामीण आजीविका को बढ़ावा देने के लिए प्रतिष्ठित राष्ट्रीय स्तर के ''सरस मेला 2026'' की मेजबानी किस शहर में की गई थी?', 'Guntur, Andhra Pradesh', 'Pune, Maharashtra', 'Kochi, Kerala', 'Bhopal, Madhya Pradesh', 'गुंटूर, आंध्र प्रदेश', 'पुणे, महाराष्ट्र', 'कोच्चि, केरल', 'भोपाल, मध्य प्रदेश', 1, 'The National Saras Fair 2026, aimed at economically empowering women self-help group members, was hosted in Guntur, Andhra Pradesh, and inaugurated by CM N. Chandrababu Naidu.', 'महिला स्वयं सहायता समूह के सदस्यों को आर्थिक रूप से सशक्त बनाने के उद्देश्य से राष्ट्रीय सरस मेला 2026 की मेजबानी गुंटूर, आंध्र प्रदेश में की गई और इसका उद्घाटन सीएम एन. चंद्रबाबू नायडू ने किया।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 30, 'The proposed third district of Goa, "Kushawati", derives its name from which of the following geographical features?', 'गोवा के प्रस्तावित तीसरे जिले "कुशावती" का नाम निम्नलिखित में से किस भौगोलिक विशेषता से लिया गया है?', 'A local mountain peak', 'A historical fort', 'A river flowing through southern Goa', 'A prominent plateau', 'एक स्थानीय पर्वत शिखर', 'एक ऐतिहासिक किला', 'दक्षिणी गोवा से बहने वाली एक नदी', 'एक प्रमुख पठार', 3, 'Kushawati, the proposed third district of Goa (adding to North and South Goa), is named after the Kushawati river that flows through the southern part of the state.', 'कुशावती, गोवा का प्रस्तावित तीसरा जिला (उत्तरी और दक्षिणी गोवा में जुड़ने वाला), कुशावती नदी के नाम पर रखा गया है जो राज्य के दक्षिणी भाग से बहती है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 31, 'Bhagirathpura locality was recently declared an epidemic zone due to a fatal waterborne E. coli outbreak. In which state is it located?', 'घातक जलजनित ई. कोलाई (E. coli) प्रकोप के कारण हाल ही में भागीरथपुरा इलाके को महामारी क्षेत्र घोषित किया गया था। यह किस राज्य में स्थित है?', 'Gujarat', 'Madhya Pradesh', 'Uttar Pradesh', 'Rajasthan', 'गुजरात', 'मध्य प्रदेश', 'उत्तर प्रदेश', 'राजस्थान', 2, 'Bhagirathpura is a locality in Indore, Madhya Pradesh, which was declared an epidemic zone following an outbreak of the waterborne E. coli bacteria that resulted in several infections and deaths.', 'भागीरथपुरा इंदौर, मध्य प्रदेश का एक इलाका है, जिसे जलजनित ई. कोलाई बैक्टीरिया के प्रकोप के बाद एक महामारी क्षेत्र घोषित किया गया था, जिसके परिणामस्वरूप कई संक्रमण और मौतें हुईं।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 32, '''Awaazon Ke Jugnu'', launched by the Indira Gandhi National Centre for the Arts (IGNCA), is best described as:', 'इंदिरा गांधी राष्ट्रीय कला केंद्र (IGNCA) द्वारा लॉन्च किया गया ''आवाजों के जुगनू'' (Awaazon Ke Jugnu) को सबसे अच्छी तरह से वर्णित किया जा सकता है:', 'A scholarship scheme for visually impaired classical singers.', 'A book and audio documentary preserving the journeys of popular radio and broadcast voices of India.', 'An AI-driven voice translation tool for all 22 scheduled languages.', 'A national-level singing competition for tribal youth.', 'दृष्टिबाधित शास्त्रीय गायकों के लिए एक छात्रवृत्ति योजना।', 'भारत की लोकप्रिय रेडियो और प्रसारण आवाज़ों की यात्रा को संरक्षित करने वाली एक पुस्तक और ऑडियो वृत्तचित्र।', 'सभी 22 अनुसूचित भाषाओं के लिए एक AI-संचालित वॉयस अनुवाद टूल।', 'आदिवासी युवाओं के लिए एक राष्ट्रीय स्तर की गायन प्रतियोगिता।', 2, '''Awaazon Ke Jugnu'' is a book and audio format project by IGNCA to document and preserve the legacy of 31 popular radio, voice-over, and broadcast voices of India.', '''आवाजों के जुगनू'' भारत की 31 लोकप्रिय रेडियो, वॉयस-ओवर और प्रसारण आवाज़ों की विरासत को दस्तावेज और संरक्षित करने के लिए IGNCA की एक पुस्तक और ऑडियो प्रारूप परियोजना है।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 33, 'Who created history at the 77th Republic Day parade by becoming the first female officer to assist the President of India in unfurling the national flag?', '77वें गणतंत्र दिवस परेड में भारत के राष्ट्रपति को राष्ट्रीय ध्वज फहराने में सहायता करने वाली पहली महिला अधिकारी बनकर किसने इतिहास रचा?', 'Swati Shanta Kumar', 'Sita Ashok Shelke', 'Akhita Dhankar', 'Simran Bala', 'स्वाति शांता कुमार', 'सीता अशोक शेलके', 'अक्षिता धनखड़', 'सिमरन बाला', 3, 'Flight Lieutenant Akhita Dhankar, hailing from Kasni village in Haryana, created history by becoming the first female IAF officer to assist the President in unfurling the tricolor at the Republic Day parade.', 'हरियाणा के कासनी गांव की रहने वाली फ्लाइट लेफ्टिनेंट अक्षिता धनखड़ ने गणतंत्र दिवस परेड में राष्ट्रपति को तिरंगा फहराने में सहायता करने वाली पहली महिला IAF अधिकारी बनकर इतिहास रच दिया।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 34, 'In January 2026, UIDAI launched an official AI chatbot mascot to simplify Aadhaar-related services. What is its name?', 'जनवरी 2026 में, UIDAI ने आधार से संबंधित सेवाओं को सरल बनाने के लिए एक आधिकारिक AI चैटबॉट शुभंकर लॉन्च किया। इसका नाम क्या है?', 'Pancham', 'Aadhar Mitra', 'Uday', 'Pankhuri', 'पंचम', 'आधार मित्र', 'उदय', 'पंखुड़ी', 3, 'UIDAI launched ''Uday'' as its official AI chatbot mascot to assist residents with complex Aadhaar-related queries in simple language and build trust around safe usage.', 'UIDAI ने निवासियों को सरल भाषा में आधार से संबंधित जटिल प्रश्नों में सहायता करने और सुरक्षित उपयोग के प्रति विश्वास बनाने के लिए अपने आधिकारिक AI चैटबॉट शुभंकर के रूप में ''उदय'' को लॉन्च किया।');
INSERT INTO questions (quiz_id, topic_id, sort_order, question, question_hi, option_a, option_b, option_c, option_d, option_a_hi, option_b_hi, option_c_hi, option_d_hi, correct_option, explanation, explanation_hi) VALUES ((SELECT id FROM quizzes WHERE title = '' ORDER BY id DESC LIMIT 1), 1267, 35, 'According to the Global Risks Report 2026 released by the World Economic Forum (WEF), what has been identified as the biggest global risk in the short term (2-year horizon)?', 'विश्व आर्थिक मंच (WEF) द्वारा जारी वैश्विक जोखिम रिपोर्ट 2026 के अनुसार, अल्पावधि (2 वर्ष के क्षितिज) में सबसे बड़ा वैश्विक जोखिम किसे माना गया है?', 'Geoeconomic Confrontation', 'Extreme Weather Events', 'Artificial Intelligence Misinformation', 'Cyber Insecurity', 'भू-आर्थिक टकराव (Geoeconomic Confrontation)', 'चरम मौसमी घटनाएं (Extreme Weather Events)', 'कृत्रिम बुद्धिमत्ता दुष्प्रचार (AI Misinformation)', 'साइबर असुरक्षा (Cyber Insecurity)', 1, 'The WEF''s 21st Global Risks Report 2026 identifies ''Geoeconomic Confrontation'' (tariffs, trade sanctions, investment restrictions) as the biggest global risk in the short term.', 'WEF की 21वीं वैश्विक जोखिम रिपोर्ट 2026 अल्पावधि में ''भू-आर्थिक टकराव'' (टैरिफ, व्यापार प्रतिबंध, निवेश प्रतिबंध) को सबसे बड़े वैश्विक जोखिम के रूप में पहचानती है।');